import sys
from pathlib import Path, PurePath

import yaml


def rule_paths(rule: Path) -> list[str]:
    text = rule.read_text()
    if not text.startswith("---\n"):
        return []
    return yaml.safe_load(text.split("---")[1]).get("paths", [])


def lines(path: Path) -> int:
    return len(path.read_text().splitlines())


rules = sorted(Path(".claude/rules").glob("*.md"))
always = [Path("CLAUDE.md")] + [r for r in rules if not rule_paths(r)]
print("at launch:", ", ".join(f"{p} ({lines(p)} lines)" for p in always))
for opened in sys.argv[1:]:
    loaded = [r for r in rules if any(PurePath(opened).full_match(g) for g in rule_paths(r))]
    print(f"opening {opened} loads:", ", ".join(str(r) for r in loaded) or "nothing more")
EOF
